The following code is a simple context manager that acquires three resources in order. If any of the middle steps fail, all previously acquired resources are released.
class MultiResource:
    def __init__(self):
        self.r1 = None
        self.r2 = None
        self.r3 = None
    def __enter__(self):
        self.r1 = Resource('r1')
        try:
            self.r2 = Resource('r2')
            try:
                self.r3 = Resource('r3')
            except:
                self.r2.release()
                raise
        except:
            self.r1.release()
            raise
        return self.r1, self.r2, self.r3
    def __exit__(self, exc_type, exc_value, traceback):
        self.r3.release()
        self.r2.release()
        self.r1.release()
        return False
